```java
import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) { in = is; }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c, s = 1, x = 0;
            do { c = read(); } while (c <= 32 && c != -1);
            if (c == '-') { s = -1; c = read(); }
            for (; c > 32; c = read()) x = x * 10 + (c - '0');
            return x * s;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        // 存储拼接后的所有星能值
        ArrayList<Integer> seq = new ArrayList<>(200000);
        for (int i = 0; i < n; i++) {
            int m = fs.nextInt();
            int[] arr = new int[m];
            for (int j = 0; j < m; j++) arr[j] = fs.nextInt();
            // 区域内升序排序
            Arrays.sort(arr);
            // 按区域顺序拼接到序列
            for (int x : arr) seq.add(x);
        }
        // 严格递增子序列长度（牌堆法 + 二分）
        int[] tails = new int[seq.size()];
        int len = 0;
        for (int x : seq) {
            int pos = lowerBound(tails, 0, len, x);
            tails[pos] = x;
            if (pos == len) len++;
        }
        System.out.println(len);
    }

    // 在 [l, r) 内查找第一个 >= x 的位置
    static int lowerBound(int[] a, int l, int r, int x) {
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (a[mid] >= x) r = mid;
            else l = mid + 1;
        }
        return l;
    }
}
