### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<int> seq;
    seq.reserve(200000);
    for (int i = 0; i < n; ++i) {
        int m;
        cin >> m;
        vector<int> a(m);
        for (int j = 0; j < m; ++j) cin >> a[j];
        // 区域内按星能值升序排序
        sort(a.begin(), a.end());
        // 按区域顺序拼接到总序列
        for (int x : a) seq.push_back(x);
    }
    // 严格递增子序列长度（牌堆法 + lower_bound）
    vector<int> tails;
    tails.reserve(seq.size());
    for (int x : seq) {
        auto it = lower_bound(tails.begin(), tails.end(), x);
        if (it == tails.end()) tails.push_back(x);
        else *it = x;
    }
    cout << (int)tails.size() << '\n';
    return 0;
}
